"""Choose reply language from the latest question, never from source documents."""
import re

def detect_language(question, history=None):
    text=re.sub(r'\b(?:[A-Za-z]+\d+|\d+[A-Za-z]+\d+)\b',' ',question)
    words=re.findall(r'[A-Za-z]+|[\u0621-\u064a]+',text)
    if not words:
        return detect_language(history[-1]) if history else 'ar'
    first=words[0].lower()
    if first in {'what','which','how','when','where','why','who','can','could','would','will','is','are',
                 'do','does','did','please','tell','explain','i','my','and','if','prerequisite','prerequisites','credits'}:
        return 'en'
    if re.search(r'[\u0621-\u064a]',first):return 'ar'
    english=sum(bool(re.fullmatch('[A-Za-z]+',w)) for w in words)
    return 'en' if english>=len(words)-english else 'ar'

def choose(arabic,english,language):
    return english if language=='en' else arabic

